package app.lernet.engine.net.observation

/**
 * Explanations shared by both clients. They describe evidence, never infer packet delivery.
 * Semantics checked against primary OS documentation:
 * https://learn.microsoft.com/en-us/powershell/module/nettcpip/get-netroute
 * https://learn.microsoft.com/en-us/windows/security/threat-protection/auditing/event-5157
 * https://developer.android.com/develop/connectivity/network-ops/reading-network-state
 */
data class SourceGuide(val meaning: String, val inspect: String, val attention: String, val limits: String)
data class FieldGuide(val label: String, val meaning: String)
data class RowGuide(val summary: String, val interpretation: String)

object ObservationGuide {
    val sourceIds: Set<String> get() = sources.keys
