    fun availability(source: ObservationSource): String = when (source.state) {
        SourceState.AVAILABLE -> if (source.complete) "Источник прочитан. Ниже — настройки на момент снимка, а не проверка передачи пакетов." else "Часть записей прочитана. По этой выборке нельзя уверенно заключать, что отсутствующие настройки не существуют."
        SourceState.EMPTY -> "Чтение завершилось, но записей в доступной области нет. Это не означает, что все связанные сетевые функции выключены."
        SourceState.ACCESS_DENIED -> "Система не разрешила чтение. Это ограничение наблюдения, а не доказательство блокировки трафика. Проверьте пользователя и доступные права."
        SourceState.UNSUPPORTED -> "ОС или установленный набор компонентов не предоставляет этот источник. Отсутствие Hyper-V или скрытые данные Android обычно ожидаемы."
        SourceState.ERROR -> "Не удалось получить или разобрать ответ источника. Состояние сети по этому пункту неизвестно; сохраните причину ошибки и обновите снимок."
        SourceState.TIMEOUT -> "Источник не завершил чтение за отведённое время. Это таймаут сбора сведений, а не измерение задержки VPN."
    }

    /** Ordinary local/multicast entries should not generate an internet-path conflict. */
    fun isServiceRoute(route: ObservedRoute, adapter: ObservedAdapter?): Boolean {
        val ip = route.prefix.substringBefore('/').substringBefore('%').lowercase()
        if (ip == "::1" || ip.startsWith("ff") || Regex("^fe[89ab][0-9a-f]:").containsMatchIn(ip)) return true
        val octets = ip.split('.').mapNotNull(String::toIntOrNull)
        if (octets.size != 4) return false
        if (octets[0] == 127 || octets[0] in 224..239 || ip == "255.255.255.255" || ip.startsWith("169.254.")) return true
        if (!route.prefix.endsWith("/32")) return false
        val address = ipv4(ip) ?: return false
        return adapter?.addresses.orEmpty().any { local ->
            val own = ipv4(local.substringBefore('/')) ?: return@any false
            val bits = local.substringAfter('/', "32").toIntOrNull() ?: return@any false
            if (bits !in 0..32) return@any false
            val mask = if (bits == 0) 0L else (0xffffffffL shl (32 - bits)) and 0xffffffffL
            address == own || (bits < 31 && address == ((own and mask) or (mask xor 0xffffffffL)))
        }
    }
    private fun ipv4(value: String): Long? {
        val parts = value.split('.')
        if (parts.size != 4) return null
        val numbers = parts.map { it.toIntOrNull()?.takeIf { n -> n in 0..255 } ?: return null }
        return numbers.fold(0L) { n, octet -> (n shl 8) or octet.toLong() }
    }

    fun row(sourceId: String, row: EvidenceRow, snapshot: NetworkSnapshot?): RowGuide {
        val f = row.fields
        fun v(vararg keys: String) = keys.firstNotNullOfOrNull { f[it]?.takeIf(String::isNotBlank) }.orEmpty()
        val index = v("InterfaceIndex", "ifIndex", "Номер интерфейса").toIntOrNull()
        val adapter = snapshot?.adapters?.firstOrNull { it.index == index } ?: snapshot?.adapters?.firstOrNull { it.id == row.id || it.name == row.title }
        return when (sourceId) {
            "routes", "persistent-routes" -> {
                val prefix = v("DestinationPrefix").ifBlank { row.title }
                val gateway = v("NextHop", "Следующий узел", "Шлюз")
                val name = v("InterfaceAlias", "Интерфейс").ifBlank { adapter?.name ?: "интерфейс ${index ?: "не указан"}" }
                val target = if (prefix in setOf("0.0.0.0/0", "::/0")) "Общий путь для адресов без более точного правила" else "Путь к адресам $prefix"
                val hop = if (gateway in setOf("0.0.0.0", "::", "на интерфейсе")) "без отдельного шлюза, на интерфейсе" else "через $gateway"
                RowGuide("$target · $name · $hop", if (v("Действие").contains("отклоняется")) "Android сообщил отклоняющий маршрут: он не передаёт пакеты к этому назначению." else if (v("Действие").contains("Продолжить поиск")) "Android передаёт дальнейший выбор другой таблице. Эта запись не задаёт конечный интерфейс и не доказывает отказ." else if (adapter?.up == false)
                    "Адаптер «${adapter.name}» отключён в этом снимке. Запись требует проверки для нужного адреса; её наличие не доказывает, что Windows выбирает именно этот путь."
                else if (sourceId == "persistent-routes") "Это сохранённое правило. Проверьте, есть ли оно в текущей таблице, прежде чем считать его действующим."
                else "Запись описывает направление передачи. Доступность шлюза и ответ сайта этим снимком не проверялись.")
            }
            "adapters" -> RowGuide(adapter?.let { "${it.name} · ${if (it.up) "интерфейс включён" else "интерфейс отключён"} · ${it.description}" } ?: "${row.title} · ${v("Status", "Подключение")}",
                if (v("InterfaceDescription").contains("WAN Miniport", true)) "Штатный виртуальный компонент Windows. Его присутствие и статус Up не означают, что VPN подключён."
                else "Сопоставьте этот интерфейс с маршрутом проблемного адреса. Включение интерфейса не подтверждает работу интернета.")
            "vpn-user", "vpn-global" -> RowGuide("${row.title} · ${v("TunnelType")} · ${fieldValue("ConnectionStatus", v("ConnectionStatus"))}",
                if (v("ConnectionStatus").equals("Disconnected", true)) "Профиль сохранён, но Windows сообщает, что это подключение отключено. Работа службы VPN не меняет этот факт." else "Состояние относится к встроенному VPN Windows. Доступность ресурса через него нужно проверить отдельно.")
            "connections" -> RowGuide("${v("ProcessName").ifBlank { row.title }} · ${v("RemoteAddress")}:${v("RemotePort")} · ${fieldValue("State", v("State"))}",
                when (v("State")) { "Established" -> "TCP-соединение установлено. Ответ HTTP, VPN-маршрут и работоспособность приложения этим не подтверждены."
                    "TimeWait" -> "Недавно закрытое соединение временно сохраняется системой. Обычно это нормально."
                    "Bound" -> "Программа выделила локальный сокет; это не установленное соединение с сервером."
                    "SynSent" -> "Отправлен запрос установки TCP, ответа ещё нет. Только повторные снимки покажут, задержалось ли соединение."
                    else -> "Состояние относится к одному TCP-сокету в момент чтения. Для вывода о сбое нужно время и результат запроса." })
            "processes", "services", "installed-apps" -> RowGuide("${row.title} · ${v("ExecutablePath", "InstallLocation", "ProcessId").ifBlank { "путь не предоставлен" }}",
                "Наличие программы или процесса не назначает его владельцем VPN. Сопоставьте PID, путь, родителя и сетевые соединения.")
            "firewall-rules", "wfp" -> RowGuide("${row.title} · ${fieldValue("Action", v("Action"))} · ${fieldValue("Direction", v("Direction"))}",
                "Для срабатывания должны совпасть условия правила. Одно слово Block не доказывает, что остановлен именно ваш запрос.")
            "adapter-counters" -> RowGuide("Накопленные счётчики · ${row.title}", "Большое число байтов нормально. Ищите рост ошибок и отбросов между двумя снимками того же адаптера.")
            "events", "trace-events" -> RowGuide("${row.title} · ${v("Время UTC", "TimeCreated")}", "Сопоставьте время, программу и адрес с воспроизведением проблемы. Старая запись не объясняет нынешнее состояние автоматически.")
            else -> RowGuide(row.title, source(sourceId, snapshot?.platform.orEmpty()).inspect)
        }
    }

