    }
    fun fieldValue(key: String, value: String): String = when {
        key == "ProxyEnable" && value == "0" -> "Нет"
        key == "ProxyEnable" && value == "1" -> "Да"
        key == "ConnectionStatus" && value == "Disconnected" -> "Отключён"
        key == "ConnectionStatus" && value == "Connected" -> "Подключён"
        value == "Established" -> "TCP установлен"
        value == "TimeWait" -> "Недавно закрыто"
        value == "SynSent" -> "Ждёт установки TCP"
        value == "Bound" -> "Локальный сокет выделен"
        value == "Up" -> "Интерфейс включён"
        value == "Disconnected" -> "Отключён"
        value == "Inbound" -> "Входящее"
        value == "Outbound" -> "Исходящее"
        value == "Allow" -> "Разрешить"
        value == "Block" -> "Блокировать"
        value.equals("true", true) -> "Да"
        value.equals("false", true) -> "Нет"
        else -> value.ifBlank { "Не указано" }
    }
}
